"use client";

import * as React from "react";
import { User } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type DivBase = { [key in keyof DivProps as key extends "defaultValue" | "onChange" | "title" ? never : key]: DivProps[key] };

export type DragSelectItem = {
  id: string;
  label: React.ReactNode;
  /** One-line preview shown after the label; it is hidden while the group is narrower than 560 px. */
  description?: React.ReactNode;
  /** Right-aligned detail such as a time, a size or a status. */
  meta?: React.ReactNode;
  avatarUrl?: string;
  disabled?: boolean;
};

export type DragSelectMode = "select" | "deselect";

export type DragSelectCheckboxGroupProps = DivBase & {
  items: DragSelectItem[];
  value?: string[];
  defaultValue?: string[];
  /** Fires once per committed change: a click, a Shift range, a key, select all, or the release of a drag. */
  onValueChange?: (ids: string[]) => void;
  /** Fires when a drag is released, with the ids the stroke changed and whether it checked or cleared them. */
  onDragSelectEnd?: (ids: string[], mode: DragSelectMode) => void;
  header?: { title: React.ReactNode; actions?: React.ReactNode };
  /** Show the select-all checkbox in the header. */
  selectAll?: boolean;
  /** Ctrl/⌘+A inside the list checks every row. */
  selectAllShortcut?: boolean;
  rowHeight?: number;
  /** How long a finger rests on a checkbox before a drag begins; a shorter tap toggles that row. */
  longPressDelay?: number;
  /** Called when a person starts to interact (pointer, key or change). Hosts use it to stop tours or demos. */
  onInteractionStart?: (event: React.SyntheticEvent) => void;
  "aria-label"?: string;
};

type RowBox = { top: number; height: number };
type Drag = {
  pointerId: number;
  start: number;
  current: number;
  target: boolean;
  before: string[];
  started: boolean;
  timer: number;
  x: number;
  y: number;
  rows: RowBox[];
  detach: () => void;
};
type Live = { lo: number; hi: number; current: number; target: boolean; draft: string[] };

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const DIGITS = Array.from({ length: 10 }, (_, index) => index);
const TICK_MS = 180;
const STAGGER_MS = 60;
const MOVE_SLOP = 8;
const BAND = "color-mix(in oklch, var(--color-primary) 7%, transparent)";

const sameIds = (a: string[], b: string[]) => a.length === b.length && a.every((id, index) => id === b[index]);

/** Ids of `items` that end up checked when rows lo..hi are set to `on` and every other row keeps its `base` state. */
function applyRange(base: string[], items: DragSelectItem[], lo: number, hi: number, on: boolean) {
  const next: string[] = [];
  items.forEach((item, index) => {
    const inRange = index >= lo && index <= hi && !item.disabled;
    const was = base.includes(item.id);
    if (inRange ? on : was) next.push(item.id);
  });
  return next;
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function Roll({ text, reduced, className = "" }: { text: string; reduced: boolean; className?: string }) {
  const chars = Array.from(text);
  return (
    <span data-roll={text} className={`inline-flex items-end leading-none whitespace-nowrap tabular-nums ${className}`}>
      <span className="sr-only">{text}</span>
      {chars.map((character, index) => {
        const key = chars.length - index;
        if (!/\d/.test(character)) return <span key={key} aria-hidden="true" className="block h-[1em]">{character === " " ? "\u00A0" : character}</span>;
        return (
          <span key={key} aria-hidden="true" className="relative block h-[1em] w-[0.62em] overflow-hidden">
            <span
              data-digit={character}
              className="block"
              style={{ transform: `translateY(-${character}em)`, transition: reduced ? "none" : `transform 200ms ${EASE}` }}
            >
              {DIGITS.map((digit) => <span key={digit} className="block h-[1em] text-center">{digit}</span>)}
            </span>
          </span>
        );
      })}
    </span>
  );
}

type BoxProps = {
  checked: boolean;
  mixed?: boolean;
  reduced: boolean;
  delay?: number;
  children: React.ReactNode;
};

function Box({ checked, mixed = false, reduced, delay = 0, children }: BoxProps) {
  const pathRef = React.useRef(null as SVGPathElement | null);
  const was = React.useRef(checked);

  React.useLayoutEffect(() => {
    const path = pathRef.current;
    const became = checked && !was.current;
    was.current = checked;
    if (!path) return;
    for (const running of path.getAnimations()) running.cancel();
    path.style.strokeDashoffset = checked ? "0" : "1";
    if (!became || reduced || typeof path.animate !== "function") return;
    path.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: TICK_MS, delay, easing: "ease-out", fill: "backwards" });
  }, [checked, reduced]);

  const on = checked || mixed;
  return (
    <span data-box data-state={mixed ? "mixed" : checked ? "checked" : "unchecked"} className="relative size-[18px] shrink-0">
      {children}
      <span
        data-face
        aria-hidden="true"
        style={{ transitionDelay: delay ? `${delay}ms` : undefined }}
        className={`pointer-events-none absolute inset-0 rounded-md ring-1 transition-[background-color,box-shadow] duration-150 ease-out motion-reduce:transition-none peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-card ${on ? "bg-primary ring-primary" : "bg-background ring-border group-hover/row:ring-muted-foreground/60 peer-hover:ring-muted-foreground/60"}`}
      >
        <svg viewBox="0 0 18 18" className="size-full" aria-hidden="true">
          <path
            ref={pathRef}
            data-tick
            d="M4.6 9.4 7.6 12.3 13.4 5.9"
            pathLength={1}
            fill="none"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="stroke-primary-foreground"
            style={{ strokeDasharray: 1, strokeDashoffset: checked ? 0 : 1 }}
          />
          <path
            data-mixed-bar
            d="M5 9h8"
            fill="none"
            strokeWidth={2}
            strokeLinecap="round"
            className="stroke-primary-foreground transition-opacity duration-100 motion-reduce:transition-none"
            style={{ opacity: mixed && !checked ? 1 : 0 }}
          />
        </svg>
      </span>
    </span>
  );
}

type RowProps = {
  item: DragSelectItem;
  index: number;
  checked: boolean;
  inBand: boolean;
  tabStop: boolean;
  rowHeight: number;
  reduced: boolean;
  delay: number;
  labelId: string;
  descriptionId: string;
  registerRow: (node: HTMLLabelElement | null) => void;
  registerInput: (node: HTMLInputElement | null) => void;
  onPointerDown: (event: React.PointerEvent) => void;
  onChange: (event: React.ChangeEvent) => void;
  onFocus: () => void;
};

function Row({ item, index, checked, inBand, tabStop, rowHeight, reduced, delay, labelId, descriptionId, registerRow, registerInput, onPointerDown, onChange, onFocus }: RowProps) {
  const disabled = !!item.disabled;
  return (
    <label
      ref={registerRow}
      data-row={item.id}
      data-index={index}
      data-checked={checked ? "true" : "false"}
      data-in-band={inBand ? "true" : "false"}
      data-disabled={disabled ? "true" : undefined}
      style={{ height: rowHeight }}
      className={`group/row relative flex w-full items-center gap-3 px-3 text-sm transition-colors duration-150 motion-reduce:transition-none ${disabled ? "cursor-not-allowed opacity-50" : "cursor-pointer hover:bg-muted/40"} ${checked ? "bg-muted/60" : ""}`}
    >
      <Box checked={checked} reduced={reduced} delay={delay}>
        <input
          ref={registerInput}
          type="checkbox"
          checked={checked}
          disabled={disabled}
          tabIndex={tabStop ? 0 : -1}
          aria-labelledby={labelId}
          aria-describedby={item.description !== undefined ? descriptionId : undefined}
          onPointerDown={onPointerDown}
          onChange={onChange}
          onFocus={onFocus}
          className={`peer absolute inset-0 z-10 m-0 size-full appearance-none opacity-0 outline-none ${disabled ? "cursor-not-allowed" : "cursor-pointer touch-none"}`}
        />
      </Box>
      {item.avatarUrl ? (
        <img src={item.avatarUrl} alt="" width={20} height={20} loading="lazy" className="size-5 shrink-0 rounded-full object-cover ring-1 ring-border" />
      ) : (
        <span aria-hidden="true" className="flex size-5 shrink-0 items-center justify-center rounded-full bg-muted text-muted-foreground">
          <User className="size-3" />
        </span>
      )}
      <span className="flex min-w-0 flex-1 items-baseline gap-2">
        <span className="grid min-w-0 max-w-full shrink-0">
          <span id={labelId} data-label className={`col-start-1 row-start-1 truncate ${checked ? "font-medium" : ""}`}>{item.label}</span>
          <span aria-hidden="true" className="invisible col-start-1 row-start-1 truncate font-medium">{item.label}</span>
        </span>
        {item.description !== undefined && (
          <span id={descriptionId} data-description className="min-w-0 flex-1 truncate text-muted-foreground @max-[560px]:hidden">{item.description}</span>
        )}
      </span>
      {item.meta !== undefined && <span data-meta className="shrink-0 text-xs tabular-nums text-muted-foreground">{item.meta}</span>}
    </label>
  );
}

export function DragSelectCheckboxGroup({
  items,
  value,
  defaultValue,
  onValueChange,
  onDragSelectEnd,
  header,
  selectAll = true,
  selectAllShortcut = true,
  rowHeight = 48,
  longPressDelay = 300,
  onInteractionStart,
  "aria-label": ariaLabel = "Items",
  className = "",
  ref,
  ...rest
}: DragSelectCheckboxGroupProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const titleId = `${baseId}-title`;
  const [local, setLocal] = React.useState(() => defaultValue ?? value ?? []);
  const [live, setLive] = React.useState(null as Live | null);
  const [focusIndex, setFocusIndex] = React.useState(() => items.findIndex((item) => !item.disabled));
  const [announce, setAnnounce] = React.useState("");

  const order = (ids: string[]) => items.filter((item) => ids.includes(item.id)).map((item) => item.id);
  const committed = order(value ?? local);
  const selected = live ? order(live.draft) : committed;
  const onMap: { [id: string]: true } = {};
  for (const id of selected) onMap[id] = true;
  const enabled = items.filter((item) => !item.disabled);
  const allOn = enabled.length > 0 && enabled.every((item) => onMap[item.id]);
  const mixed = !allOn && selected.length > 0;
  const count = selected.length;

  const rowsRef = React.useRef(null as HTMLDivElement | null);
  const rowRefs = React.useRef([] as (HTMLLabelElement | null)[]);
  const inputRefs = React.useRef([] as (HTMLInputElement | null)[]);
  const allRef = React.useRef(null as HTMLInputElement | null);
  const dragRef = React.useRef(null as Drag | null);
  const anchorRef = React.useRef(null as number | null);
  const skipClick = React.useRef(false);
  const staggerRef = React.useRef({} as { [id: string]: number });
  const staggerTimer = React.useRef(0);

  const commit = (next: string[]) => {
    const ordered = order(next);
    if (sameIds(ordered, committed)) return false;
    if (value === undefined) setLocal(ordered);
    onValueChange?.(ordered);
    return true;
  };
  const latest = React.useRef({ items, committed, commit, onDragSelectEnd });
  latest.current = { items, committed, commit, onDragSelectEnd };

  React.useEffect(() => {
    if (allRef.current) allRef.current.indeterminate = mixed;
  }, [mixed]);

  React.useEffect(() => () => {
    const drag = dragRef.current;
    if (drag) { window.clearTimeout(drag.timer); drag.detach(); }
    window.clearTimeout(staggerTimer.current);
  }, []);

  const speak = (ids: string[]) => setAnnounce(`${ids.length} selected`);

  const stagger = (turningOn: string[]) => {
    const map: { [id: string]: number } = {};
    turningOn.forEach((id, index) => { map[id] = Math.min(index, 12) * STAGGER_MS; });
    staggerRef.current = map;
    window.clearTimeout(staggerTimer.current);
    staggerTimer.current = window.setTimeout(() => { staggerRef.current = {}; }, Math.min(turningOn.length, 13) * STAGGER_MS + TICK_MS + 200);
  };

  const setAll = (on: boolean) => {
    const next = items.filter((item) => (item.disabled ? !!onMap[item.id] : on)).map((item) => item.id);
    if (on) stagger(enabled.filter((item) => !onMap[item.id]).map((item) => item.id));
    if (commit(next)) speak(next);
  };

  const onAllChange = (event: React.ChangeEvent) => {
    onInteractionStart?.(event);
    setAll(!allOn);
  };

  const onRowChange = (index: number) => (event: React.ChangeEvent) => {
    // A click that ends a drag has already been applied; React restores the controlled state.
    if (skipClick.current) return;
    const item = items[index];
    if (!item || item.disabled) return;
    onInteractionStart?.(event);
    const native = event.nativeEvent;
    const shift = native instanceof MouseEvent && native.shiftKey;
    const on = !onMap[item.id];
    const anchor = anchorRef.current;
    let next: string[];
    if (shift && anchor !== null && anchor !== index) {
      next = applyRange(committed, items, Math.min(anchor, index), Math.max(anchor, index), on);
    } else {
      next = applyRange(committed, items, index, index, on);
      anchorRef.current = index;
    }
    setFocusIndex(index);
    if (commit(next)) speak(next);
  };

  const indexAt = (drag: Drag, clientY: number) => {
    const rows = rowsRef.current;
    if (!rows || drag.rows.length === 0) return drag.current;
    const y = clientY - rows.getBoundingClientRect().top;
    if (y < 0) return 0;
    for (let index = 0; index < drag.rows.length; index++) {
      const box = drag.rows[index];
      if (box && y < box.top + box.height) return index;
    }
    return drag.rows.length - 1;
  };

  const update = (drag: Drag, index: number) => {
    drag.current = index;
    const lo = Math.min(drag.start, index);
    const hi = Math.max(drag.start, index);
    setLive({ lo, hi, current: index, target: drag.target, draft: applyRange(drag.before, latest.current.items, lo, hi, drag.target) });
  };

  const begin = (drag: Drag) => {
    drag.started = true;
    skipClick.current = true;
    drag.rows = rowRefs.current.map((node) => (node ? { top: node.offsetTop, height: node.offsetHeight } : { top: 0, height: rowHeight }));
    update(drag, drag.start);
  };

  const drop = (drag: Drag) => {
    window.clearTimeout(drag.timer);
    drag.detach();
    dragRef.current = null;
  };

  const finish = (drag: Drag, how: "commit" | "revert") => {
    drop(drag);
    if (how === "commit") {
      const { items: list, commit: apply, onDragSelectEnd: ended } = latest.current;
      const lo = Math.min(drag.start, drag.current);
      const hi = Math.max(drag.start, drag.current);
      const draft = applyRange(drag.before, list, lo, hi, drag.target);
      const changed = list.slice(lo, hi + 1).filter((item) => !item.disabled && drag.before.includes(item.id) !== drag.target).map((item) => item.id);
      apply(draft);
      ended?.(changed, drag.target ? "select" : "deselect");
      anchorRef.current = drag.current;
      speak(draft);
    }
    setLive(null);
    // The click that follows this pointerup is dispatched before any timer fires.
    window.setTimeout(() => { skipClick.current = false; }, 0);
  };

  const onBoxPointerDown = (index: number) => (event: React.PointerEvent) => {
    const item = items[index];
    if (!item || item.disabled) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    // Shift builds a range from the anchor; the click that follows handles it.
    if (event.shiftKey) return;
    onInteractionStart?.(event);
    const previous = dragRef.current;
    if (previous) finish(previous, "revert");
    try { event.currentTarget.setPointerCapture(event.pointerId); } catch { /* synthetic pointers cannot be captured */ }
    const move = (native: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || native.pointerId !== drag.pointerId) return;
      if (!drag.started) {
        if (Math.hypot(native.clientX - drag.x, native.clientY - drag.y) > MOVE_SLOP) drop(drag);
        return;
      }
      const next = indexAt(drag, native.clientY);
      if (next !== drag.current) update(drag, next);
    };
    const up = (native: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || native.pointerId !== drag.pointerId) return;
      if (drag.started) finish(drag, "commit");
      else drop(drag);
    };
    const cancel = (native: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || native.pointerId !== drag.pointerId) return;
      if (drag.started) finish(drag, "revert");
      else drop(drag);
    };
    const key = (native: KeyboardEvent) => {
      const drag = dragRef.current;
      if (drag && native.key === "Escape") { native.preventDefault(); if (drag.started) finish(drag, "revert"); else drop(drag); }
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", cancel);
    window.addEventListener("keydown", key);
    const drag: Drag = {
      pointerId: event.pointerId,
      start: index,
      current: index,
      target: !onMap[item.id],
      before: committed,
      started: false,
      timer: 0,
      x: event.clientX,
      y: event.clientY,
      rows: [],
      detach: () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        window.removeEventListener("pointercancel", cancel);
        window.removeEventListener("keydown", key);
      },
    };
    dragRef.current = drag;
    if (event.pointerType === "touch") drag.timer = window.setTimeout(() => { if (dragRef.current === drag) begin(drag); }, longPressDelay);
    else begin(drag);
  };

  const onRowsKeyDown = (event: React.KeyboardEvent) => {
    const positions = items.map((item, index) => (item.disabled ? -1 : index)).filter((index) => index >= 0);
    if (positions.length === 0) return;
    if ((event.key === "a" || event.key === "A") && (event.ctrlKey || event.metaKey)) {
      if (!selectAllShortcut) return;
      event.preventDefault();
      onInteractionStart?.(event);
      setAll(true);
      return;
    }
    const at = positions.indexOf(focusIndex);
    let next = -1;
    if (event.key === "ArrowDown") next = Math.min(positions.length - 1, at + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, at - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = positions.length - 1;
    else return;
    event.preventDefault();
    onInteractionStart?.(event);
    const target = positions[next];
    if (target === undefined) return;
    setFocusIndex(target);
    inputRefs.current[target]?.focus({ preventScroll: true });
  };

  const focusItem = items[focusIndex];
  const tabStop = focusItem && !focusItem.disabled ? focusIndex : items.findIndex((item) => !item.disabled);
  const geometry = live && dragRef.current ? dragRef.current.rows : null;
  const bandTop = geometry && live ? geometry[live.lo]?.top ?? 0 : 0;
  const bandEnd = geometry && live ? (geometry[live.hi]?.top ?? 0) + (geometry[live.hi]?.height ?? rowHeight) : 0;
  const edgeTop = geometry && live ? (geometry[live.current]?.top ?? 0) - bandTop : 0;
  const edgeHeight = geometry && live ? geometry[live.current]?.height ?? rowHeight : rowHeight;
  const titleIsText = typeof header?.title === "string";

  return (
    <div
      ref={ref}
      {...rest}
      data-slot="drag-select-checkbox-group"
      data-value={selected.join(",")}
      data-count={count}
      data-dragging={live ? "true" : "false"}
      data-drag-mode={live ? (live.target ? "select" : "deselect") : undefined}
      role="group"
      aria-label={header && titleIsText ? undefined : ariaLabel}
      aria-labelledby={header && titleIsText ? titleId : undefined}
      onContextMenu={(event) => { if (dragRef.current?.started) event.preventDefault(); }}
      className={`@container w-full text-foreground ${live ? "select-none" : ""} ${className}`}
    >
      {header && (
        <div data-header className="flex items-center gap-3 border-b border-border px-3" style={{ height: rowHeight }}>
          {selectAll && (
            <Box checked={allOn} mixed={mixed} reduced={reduced}>
              <input
                ref={allRef}
                data-select-all
                type="checkbox"
                checked={allOn}
                aria-checked={mixed ? "mixed" : undefined}
                aria-label="Select all"
                disabled={enabled.length === 0}
                onChange={onAllChange}
                className="peer absolute inset-0 z-10 m-0 size-full cursor-pointer appearance-none opacity-0 outline-none disabled:cursor-not-allowed"
              />
            </Box>
          )}
          <span id={titleId} data-title className="min-w-0 truncate text-sm font-semibold">{header.title}</span>
          <span className="flex-1" />
          <span data-count-roll data-empty={count === 0 ? "true" : "false"} className="text-xs text-muted-foreground transition-opacity duration-200 motion-reduce:transition-none data-[empty=true]:opacity-60">
            <Roll text={`${count} selected`} reduced={reduced} />
          </span>
          {header.actions !== undefined && (
            <div data-actions data-empty={count === 0 ? "true" : "false"} className="flex items-center gap-1 transition-opacity duration-200 motion-reduce:transition-none data-[empty=true]:opacity-40">
              {header.actions}
            </div>
          )}
        </div>
      )}
      <div data-list className="relative">
        <div ref={rowsRef} data-rows className="relative divide-y divide-border/60" onKeyDown={onRowsKeyDown}>
          {items.map((item, index) => (
            <Row
              key={item.id}
              item={item}
              index={index}
              checked={!!onMap[item.id]}
              inBand={!!live && index >= live.lo && index <= live.hi}
              tabStop={index === tabStop}
              rowHeight={rowHeight}
              reduced={reduced}
              delay={staggerRef.current[item.id] ?? 0}
              labelId={`${baseId}-label-${index}`}
              descriptionId={`${baseId}-description-${index}`}
              registerRow={(node) => { rowRefs.current[index] = node; }}
              registerInput={(node) => { inputRefs.current[index] = node; }}
              onPointerDown={onBoxPointerDown(index)}
              onChange={onRowChange(index)}
              onFocus={() => setFocusIndex(index)}
            />
          ))}
        </div>
        {live && geometry && !reduced && (
          <div
            data-band
            data-mode={live.target ? "select" : "deselect"}
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 z-10"
            style={{ top: bandTop, height: Math.max(0, bandEnd - bandTop), backgroundColor: BAND, transition: "top 140ms ease-out, height 140ms ease-out" }}
          >
            <span data-band-edge className="absolute left-0 w-0.5 rounded-full bg-primary" style={{ top: edgeTop, height: edgeHeight, transition: "top 140ms ease-out" }} />
          </div>
        )}
      </div>
      <p role="status" aria-live="polite" aria-atomic="true" className="sr-only">{announce}</p>
    </div>
  );
}

export default DragSelectCheckboxGroup;

