"use client";

import * as React from "react";
import { Archive, Trash2 } from "lucide-react";
import { DragSelectCheckboxGroup } from "@/components/ui/drag-select-checkbox-group";
import type { DragSelectItem, DragSelectMode } from "@/components/ui/drag-select-checkbox-group";

const HEADSHOTS = {
  "photo-1573497019940-1c28c88b4f3e": "data:image/webp;base64,",
  "photo-1560250097-0b93528c311a": "data:image/webp;base64,",
  "photo-1573496358961-3c82861ab8f4": "data:image/webp;base64,",
  "photo-1540569014015-19a7be504e3a": "data:image/webp;base64,",
} as const;

const SENDERS = {
