const CYCLE = 9000;
const POINTER_ID = 9001;

function fire(target: EventTarget, type: string, clientX: number, clientY: number) {
  const released = type === "pointerup" || type === "pointercancel";
  target.dispatchEvent(new PointerEvent(type, {
    bubbles: true, cancelable: true, composed: true, pointerId: POINTER_ID, pointerType: "mouse", isPrimary: true,
    button: 0, buttons: released ? 0 : 1, clientX, clientY,
  }));
}

const centre = (node: Element) => { const box = node.getBoundingClientRect(); return { x: box.left + box.width / 2, y: box.top + box.height / 2 }; };

function simulateDrag(root: HTMLElement, from: number, to: number, duration: number, hold: number, done: () => void) {
  const rows = root.querySelectorAll("[data-row]");
  const start = rows[from]?.querySelector("input");
  const end = rows[to]?.querySelector("input");
  if (!start || !end) { done(); return () => {}; }
  const a = centre(start);
  const b = centre(end);
  fire(start, "pointerdown", a.x, a.y);
  let frame = 0;
  let timer = 0;
  let released = false;
  const started = performance.now();
  const tick = (now: number) => {
    const progress = Math.min(1, (now - started) / duration);
    fire(window, "pointermove", a.x, a.y + (b.y - a.y) * progress);
    if (progress < 1) { frame = requestAnimationFrame(tick); return; }
    timer = window.setTimeout(() => { released = true; fire(window, "pointerup", b.x, b.y); done(); }, hold);
  };
  frame = requestAnimationFrame(tick);
  return () => {
    cancelAnimationFrame(frame);
    window.clearTimeout(timer);
    if (!released) { released = true; fire(window, "pointercancel", a.x, a.y); }
  };
}

function shiftClick(root: HTMLElement, index: number) {
  const input = root.querySelectorAll("[data-row]")[index]?.querySelector("input");
  input?.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, composed: true, button: 0, shiftKey: true }));
}

function press(root: HTMLElement, selector: string) {
  const node = root.querySelector(selector);
  if (node instanceof HTMLElement) node.click();
}

function ActionButton({ icon, label, disabled, onClick }: { icon: React.ReactNode; label: string; disabled: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      data-action={label.toLowerCase()}
      disabled={disabled}
      onClick={onClick}
      className="inline-flex h-7 items-center gap-1.5 rounded-md px-2 text-xs font-medium text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none motion-reduce:transition-none"
    >
      {icon}
      {label}
    </button>
  );
}

export default function Demo({ autoplay = true }: { autoplay?: boolean }) {
  const params = React.useMemo(() => new URLSearchParams(typeof location === "undefined" ? "" : location.search), []);
  const freeze = params.get("freeze") === "1";
  const uncontrolled = params.get("uncontrolled") === "1";
  const disabledId = params.get("disabled");
  const [items, setItems] = React.useState(() => MAIL.map((mail) => (mail.id === disabledId ? { ...mail, disabled: true } : mail)));
  const [value, setValue] = React.useState([] as string[]);
  const [changes, setChanges] = React.useState(0);
  const [last, setLast] = React.useState("");
  const [dragEnd, setDragEnd] = React.useState("");
  const [stopped, setStopped] = React.useState(false);
  const [stage, setStage] = React.useState("idle");
  const [note, setNote] = React.useState("");
  const rootRef = React.useRef(null as HTMLDivElement | null);
  const playing = autoplay && !stopped;

  React.useEffect(() => {
    if (!playing) return;
    const root = rootRef.current;
    if (!root) return;
    const timers: number[] = [];
    let cancelDrag = () => {};
    const run = (first: boolean) => {
      const at = (ms: number, task: () => void) => timers.push(window.setTimeout(task, ms));
      if (!first) at(0, () => { setStage("reset"); setValue([]); });
      at(500, () => { setStage("drag-down"); cancelDrag = simulateDrag(root, 1, 5, 1400, 0, () => setStage("idle")); });
      at(2800, () => { setStage("shift-click"); shiftClick(root, 6); });
      at(3800, () => { setStage("select-all"); press(root, "[data-select-all]"); });
      at(5000, () => { setStage("drag-up"); cancelDrag = simulateDrag(root, 1, 0, 350, 250, () => setStage("idle")); });
    };
    run(true);
    const loop = window.setInterval(() => run(false), CYCLE);
    return () => {
      window.clearInterval(loop);
      for (const timer of timers) window.clearTimeout(timer);
      cancelDrag();
    };
  }, [playing]);

  const stop = () => { if (autoplay) setStopped(true); };
  const remove = (verb: string) => {
    stop();
    const picked = items.filter((item) => value.includes(item.id));
    if (picked.length === 0) return;
    setItems((current) => current.filter((item) => !value.includes(item.id)));
    setValue([]);
    setNote(`${picked.length} ${picked.length === 1 ? "conversation" : "conversations"} ${verb}`);
  };
  const onValueChange = (ids: string[]) => {
    setChanges((count) => count + 1);
    setLast(ids.join(","));
    if (!freeze) setValue(ids);
  };
  const onDragSelectEnd = (ids: string[], mode: DragSelectMode) => setDragEnd(`${mode}:${ids.join(",")}`);

  return (
    <main
      data-demo-root
      data-stage={stage}
      data-playing={playing ? "true" : "false"}
      data-changes={changes}
      data-last={last}
      data-drag-end={dragEnd}
      className="flex min-h-[min(100svh,760px)] w-full items-center justify-center bg-background px-4 py-6 text-foreground sm:px-6"
    >
      <div ref={rootRef} className="w-full max-w-[640px] overflow-hidden rounded-2xl bg-card text-card-foreground shadow-sm ring-1 ring-border">
        <DragSelectCheckboxGroup
          items={items}
          {...(uncontrolled ? { defaultValue: [] as string[] } : { value })}
          onValueChange={onValueChange}
          onDragSelectEnd={onDragSelectEnd}
          onInteractionStart={(event) => { if (event.isTrusted) stop(); }}
          header={{
            title: "Inbox",
            actions: (
              <>
                <ActionButton icon={<Archive className="size-3.5" aria-hidden="true" />} label="Archive" disabled={value.length === 0} onClick={() => remove("archived")} />
                <ActionButton icon={<Trash2 className="size-3.5" aria-hidden="true" />} label="Delete" disabled={value.length === 0} onClick={() => remove("deleted")} />
              </>
            ),
          }}
          aria-label="Inbox"
        />
        {items.length === 0 && <p data-empty className="px-4 py-8 text-center text-sm text-muted-foreground">You're all caught up.</p>}
        {note && <p data-note role="status" className="border-t border-border px-4 py-2 text-xs text-muted-foreground">{note}</p>}
      </div>
    </main>
  );
}
